/* ============================================================================
   Base de dados de formação — vendas, recebimentos e conta corrente de clientes
   Dados reais ANONIMIZADOS (códigos de cliente, NIFs e nomes fictícios).
   Os indicadores financeiros das empresas clientes estão numa base MongoDB à
   parte (fin_db.fin_data) e ligam-se a esta pelo NIF (Clientes.NumContrib).
   Compatível com SQL Server 2016 ou superior.
   ========================================================================== */
USE master;
GO
IF DB_ID(N'StagingArea') IS NULL
    CREATE DATABASE StagingArea;
GO
USE StagingArea;
GO
SET NOCOUNT ON;
GO

DROP TABLE IF EXISTS dbo.CondPag;
GO
CREATE TABLE dbo.CondPag (
    [CondPag] NVARCHAR(2) NULL,
    [Descricao] NVARCHAR(35) NULL,
    [Dias] SMALLINT NULL,
    [DataUltimaActualizacao] DATETIME NULL
);
GO
DROP TABLE IF EXISTS dbo.TipoTerceiros;
GO
CREATE TABLE dbo.TipoTerceiros (
    [TipoTerceiro] NVARCHAR(3) NULL,
    [Descricao] NVARCHAR(35) NULL,
    [DataUltimaActualizacao] DATETIME NULL
);
GO
DROP TABLE IF EXISTS dbo.DocumentosVenda;
GO
CREATE TABLE dbo.DocumentosVenda (
    [Documento] NVARCHAR(5) NULL,
    [Descricao] NVARCHAR(35) NULL,
    [PagarReceber] NVARCHAR(1) NULL,
    [DataUltimaActualizacao] DATETIME NULL,
    [Inactivo] BIT NULL
);
GO
DROP TABLE IF EXISTS dbo.Clientes;
GO
CREATE TABLE dbo.Clientes (
    [Cliente] NVARCHAR(12) NULL,
    [Nome] NVARCHAR(50) NULL,
    [NumContrib] NVARCHAR(20) NULL,
    [CondPag] NVARCHAR(2) NULL,
    [TipoTerceiro] NVARCHAR(3) NULL,
    [DataCriacao] DATETIME NULL,
    [DataUltimaActualizacao] DATETIME NULL
);
GO
DROP TABLE IF EXISTS dbo.CabecDoc;
GO
CREATE TABLE dbo.CabecDoc (
    [NumDoc] INT NULL,
    [Seccao] NVARCHAR(2) NULL,
    [Serie] NVARCHAR(5) NULL,
    [Data] DATETIME NULL,
    [Entidade] NVARCHAR(12) NULL,
    [TipoDoc] NVARCHAR(5) NULL,
    [DataVencimento] DATETIME NULL,
    [TotalDocumento] FLOAT NULL
);
GO
DROP TABLE IF EXISTS dbo.Pendentes;
GO
CREATE TABLE dbo.Pendentes (
    [Entidade] NVARCHAR(12) NULL,
    [NumDoc] NVARCHAR(20) NULL,
    [NumDocInt] INT NULL,
    [DataDoc] DATETIME NULL,
    [DataVenc] DATETIME NULL,
    [ValorTotal] FLOAT NULL,
    [ValorPendente] FLOAT NULL,
    [TipoDoc] NVARCHAR(5) NULL,
    [TipoEntidade] NVARCHAR(1) NULL
);
GO
DROP TABLE IF EXISTS dbo.CabLiq;
GO
CREATE TABLE dbo.CabLiq (
    [Entidade] NVARCHAR(12) NULL,
    [NumDoc] INT NULL,
    [DataDoc] DATETIME NULL,
    [ValorRec] FLOAT NULL,
    [Serie] NVARCHAR(5) NULL,
    [DocLiq] NVARCHAR(15) NULL,
    [Id] UNIQUEIDENTIFIER NULL,
    [DataUltimaActualizacao] DATETIME NULL,
    [Anulado] BIT NULL,
    [Documento] NVARCHAR(50) NULL
);
GO
DROP TABLE IF EXISTS dbo.LinhasLiq;
GO
CREATE TABLE dbo.LinhasLiq (
    [Entidade] NVARCHAR(12) NULL,
    [TipoDoc] NVARCHAR(5) NULL,
    [Serie] NVARCHAR(5) NULL,
    [NumDoc] INT NULL,
    [DataDoc] DATETIME NULL,
    [ValorOrig] FLOAT NULL,
    [ValorRec] FLOAT NULL,
    [ValorPend] FLOAT NULL,
    [TipoDocOrig] NVARCHAR(5) NULL,
    [SerieOrig] NVARCHAR(5) NULL,
    [NumDocOrig] INT NULL,
    [IdCabLiq] UNIQUEIDENTIFIER NULL
);
GO
DROP TABLE IF EXISTS dbo.NumerosContribuinte;
GO
CREATE TABLE dbo.NumerosContribuinte (
    [NumContrib] NVARCHAR(20) NULL,
    [Estado] NVARCHAR(254) NULL,
    [Relatorio] NVARCHAR(50) NULL,
    [DataUltimaAtualizacao] DATETIME NULL
);
GO
DROP TABLE IF EXISTS dbo.LogErrosHttp;
GO
CREATE TABLE dbo.LogErrosHttp (
    [NumContrib] NVARCHAR(20) NULL,
    [Relatorio] NVARCHAR(50) NULL,
    [StatusCode] NVARCHAR(2054) NULL,
    [StatusDescription] NVARCHAR(2054) NULL,
    [DataHora] DATETIME NULL
);
GO
DROP TABLE IF EXISTS dbo.Registo;
GO
CREATE TABLE dbo.Registo (
    [DataUltimaTransacao] DATETIME NULL
);
GO

